        return EXIT_ERROR

    if not isinstance(payload, dict):
        return _emit_error(
            "INVALID_REFERENCE_INPUT", "input payload must be a JSON object"
        )

    try:
        result = validate_references(
            payload.get("datasets"),
            payload.get("rules"),
        )
    except InvalidReferenceInputError as exc:
        return _emit_error("INVALID_REFERENCE_INPUT", str(exc))
    except InvalidReferenceRuleError as exc:
        return _emit_error("INVALID_REFERENCE_RULE", str(exc))
    except UnknownReferenceDatasetError as exc:
        return _emit_error("UNKNOWN_REFERENCE_DATASET", str(exc))

    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_OK


def _run_quality_gates() -> int:
    payload = _read_json_payload()
    if payload is _PARSE_FAILED:
        return EXIT_ERROR

    if not isinstance(payload, dict):
        return _emit_error(
            "INVALID_INPUT", "input payload must be a JSON object"
        )
    for key in ("records", "rules", "gates"):
        if key not in payload:
            return _emit_error(
                "INVALID_INPUT", f"payload is missing {key!r}"
            )

    try:
        result = evaluate_quality_gates(
            payload.get("dataset"),
            payload["records"],
            payload["rules"],
            payload["gates"],
            payload.get("exemptions"),
        )
    except InvalidRuleError as exc:
        return _emit_error("INVALID_RULE", str(exc))
    except InvalidInputError as exc:
        return _emit_error("INVALID_INPUT", str(exc))
    except InvalidQualityGateRuleError as exc:
        return _emit_error("INVALID_QUALITY_GATE_RULE", str(exc))
    except UnknownQualityGateSourceError as exc:
        return _emit_error("UNKNOWN_QUALITY_GATE_SOURCE", str(exc))
    except InvalidExemptionError as exc:
        return _emit_error("INVALID_EXEMPTION_INPUT", str(exc))
    except DataQualityError as exc:
        return _emit_error(exc.code, str(exc))

    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_OK


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="dq",
        description="Data quality rule validation and lineage tracing.",
    )
    subparsers = parser.add_subparsers(dest="command", required=True)

    validate_parser = subparsers.add_parser(
        "validate",
        help="validate records from a UTF-8 JSON object on standard input",
    )
    validate_parser.set_defaults(handler=_run_validate)

    batch_validate_parser = subparsers.add_parser(
        "batch-validate",
        help="validate batch-level cross-record rules from a UTF-8 JSON "
        "object on standard input",
    )
    batch_validate_parser.set_defaults(handler=_run_batch_validate)

    profile_parser = subparsers.add_parser(
        "profile",
        help="profile records and generate validate rule candidates from "
        "a UTF-8 JSON object on standard input",
    )
    profile_parser.set_defaults(handler=_run_profile)

    exemptions_parser = subparsers.add_parser(
        "exemptions",
        help="apply manual exemptions to a dq validate result from a "
        "UTF-8 JSON object on standard input",
    )
    exemptions_parser.set_defaults(handler=_run_exemptions)

    lineage_parser = subparsers.add_parser(
        "lineage",
        help="trace upstream/downstream lineage from a UTF-8 JSON object "
        "on standard input",
    )
    lineage_parser.set_defaults(handler=_run_lineage)

    field_lineage_parser = subparsers.add_parser(
        "field-lineage",
        help="trace upstream/downstream field-level lineage from a UTF-8 "
        "JSON object on standard input",
    )
    field_lineage_parser.set_defaults(handler=_run_field_lineage)

    lineage_paths_parser = subparsers.add_parser(
        "lineage-paths",
        help="explain ordered upstream/downstream lineage paths from a "
        "UTF-8 JSON object on standard input",
    )
    lineage_paths_parser.set_defaults(handler=_run_lineage_paths)

    field_lineage_paths_parser = subparsers.add_parser(
        "field-lineage-paths",
        help="explain ordered upstream/downstream field-level lineage paths "
        "from a UTF-8 JSON object on standard input",
    )
    field_lineage_paths_parser.set_defaults(handler=_run_field_lineage_paths)

    sample_lineage_parser = subparsers.add_parser(
        "sample-lineage",
        help="trace upstream/downstream sample-level lineage from a UTF-8 "
        "JSON object on standard input",
    )
    sample_lineage_parser.set_defaults(handler=_run_sample_lineage)

    correlate_parser = subparsers.add_parser(
        "correlate",
        help="group violation results into cross-rule correlation events "
        "from a UTF-8 JSON object on standard input",
    )
    correlate_parser.set_defaults(handler=_run_correlate)

    correlate_links_parser = subparsers.add_parser(
        "correlate-links",
        help="group violation results across linked samples into "
        "cross-dataset correlation events from a UTF-8 JSON object on "
        "standard input",
    )
    correlate_links_parser.set_defaults(handler=_run_correlate_links)

    violation_origins_parser = subparsers.add_parser(
        "violation-origins",
        help="analyze upstream/self origin and downstream impact evidence "
        "of violated targets from a UTF-8 JSON object on standard input",
    )
    violation_origins_parser.set_defaults(handler=_run_violation_origins)

    field_impact_parser = subparsers.add_parser(
        "field-impact",
        help="analyze downstream field-level quality impact from a UTF-8 "
        "JSON object on standard input",
    )
    field_impact_parser.set_defaults(handler=_run_field_impact)

    query_results_parser = subparsers.add_parser(
        "query-results",
        help="filter complete composite rule results by rule id, severity "
        "or record locator from a UTF-8 JSON object on standard input",
    )
    query_results_parser.set_defaults(handler=_run_query_results)

    snapshot_diff_parser = subparsers.add_parser(
        "snapshot-diff",
        help="compare violated results of two quality check snapshots over "
        "the shared lineage graph from a UTF-8 JSON object on standard "
        "input",
    )
    snapshot_diff_parser.set_defaults(handler=_run_snapshot_diff)

    lineage_diff_parser = subparsers.add_parser(
        "lineage-diff",
        help="compare two field lineage snapshots around queried targets "
        "from a UTF-8 JSON object on standard input",
    )
    lineage_diff_parser.set_defaults(handler=_run_lineage_diff)

    reference_integrity_parser = subparsers.add_parser(
        "reference-integrity",
        help="validate cross-dataset reference integrity rules from a "
        "UTF-8 JSON object on standard input",
    )
    reference_integrity_parser.set_defaults(handler=_run_reference_integrity)

    quality_gates_parser = subparsers.add_parser(
        "quality-gates",
        help="aggregate single-field rule failure ratios into dataset-level "
        "quality gates from a UTF-8 JSON object on standard input",
    )
    quality_gates_parser.set_defaults(handler=_run_quality_gates)
    return parser


def main(argv: Optional[List[str]] = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    return args.handler()


if __name__ == "__main__":
    sys.exit(main())

"""Tests for violation origin/impact evidence analysis."""

import unittest

from data_quality import (
    InvalidOriginInputError,
    UnknownOriginReferenceError,
    UnknownOriginTargetError,
    analyze_violation_origins,
)


def result(rule_id, dataset_id, field_id, sample_id, violated=True, value=None):
    return {
        "rule_id": rule_id,
        "dataset_id": dataset_id,
        "field_id": field_id,
        "sample_id": sample_id,
        "violated": violated,
        "value": value,
    }


def endpoint(dataset, field):
    return {"dataset": dataset, "field": field}


def path_node(dataset, field):
    return {"dataset_id": dataset, "field_id": field}


def edge(src_dataset, src_field, dst_dataset, dst_field, edge_type="upstream"):
    return {
        "source": endpoint(src_dataset, src_field),
        "target": endpoint(dst_dataset, dst_field),
        "type": edge_type,
    }


def lineage(datasets, fields, edges):
    return {"datasets": datasets, "fields": fields, "edges": edges}


def target(dataset_id, field_id, sample_id):
    return {
        "dataset_id": dataset_id,
        "field_id": field_id,
        "sample_id": sample_id,
    }


# ods.name -> dwd.label -> ads.label, plus dwd.id with no edges.
BASE_LINEAGE = lineage(
    ["ods", "dwd", "ads"],
    {"ods": ["id", "name"], "dwd": ["id", "label"], "ads": ["label"]},
    [
        edge("dwd", "label", "ods", "name", "upstream"),
        edge("dwd", "label", "ads", "label", "downstream"),
    ],
)


class OriginEmptyTest(unittest.TestCase):
    def test_empty_targets_yield_empty_reports(self):
        results = [result("r1", "dwd", "label", "s1", value="bad")]
        self.assertEqual(
            analyze_violation_origins(results, BASE_LINEAGE, []),
            {"reports": []},
        )

    def test_empty_results_and_empty_targets(self):
        self.assertEqual(
            analyze_violation_origins([], BASE_LINEAGE, []), {"reports": []}
        )

    def test_no_evidence_yields_empty_lists(self):
        # dwd.id has no lineage edges and no other violation shares s1, so
        # only its own self evidence remains and nothing is impacted.
        results = [
            result("r1", "dwd", "id", "s1", value=0),
            result("r2", "dwd", "label", "s2", value="bad"),
            result("r3", "ods", "name", "s1", violated=False, value="ok"),
        ]
        reports = analyze_violation_origins(
            results, BASE_LINEAGE, [target("dwd", "id", "s1")]
        )["reports"]
        self.assertEqual(len(reports), 1)
        self.assertEqual(
            reports[0]["target"], target("dwd", "id", "s1")
        )
        self.assertEqual(
            [item["rule_id"] for item in reports[0]["originEvidence"]],
            ["r1"],
        )
        self.assertEqual(reports[0]["impactEvidence"], [])


class OriginEvidenceTest(unittest.TestCase):
    def test_self_violation_is_origin_evidence(self):
        results = [result("r1", "dwd", "label", "s1", value="bad")]
        report = analyze_violation_origins(
            results, BASE_LINEAGE, [target("dwd", "label", "s1")]
        )["reports"][0]
        self.assertEqual(len(report["originEvidence"]), 1)
        evidence = report["originEvidence"][0]
        self.assertEqual(
            evidence,
            {
                "rule_id": "r1",
                "dataset_id": "dwd",
                "field_id": "label",
                "sample_id": "s1",
                "violated": True,
                "value": "bad",
                "path": [path_node("dwd", "label")],
            },
        )
        self.assertEqual(report["impactEvidence"], [])

    def test_upstream_self_and_downstream_split(self):
        results = [
            result("r1", "ods", "name", "s1", value="x"),
            result("r2", "dwd", "label", "s1", value="y"),
            result("r3", "ads", "label", "s1", value="z"),
        ]
        report = analyze_violation_origins(
            results, BASE_LINEAGE, [target("dwd", "label", "s1")]
        )["reports"][0]

        self.assertEqual(
            [item["rule_id"] for item in report["originEvidence"]],
            ["r2", "r1"],
        )
        self.assertEqual(
            report["originEvidence"][1]["path"],
            [path_node("ods", "name"), path_node("dwd", "label")],
        )
        self.assertEqual(
            [item["rule_id"] for item in report["impactEvidence"]], ["r3"]
        )
        self.assertEqual(
            report["impactEvidence"][0]["path"],
            [path_node("dwd", "label"), path_node("ads", "label")],
        )

    def test_transitive_upstream_path(self):
        results = [
            result("r1", "ods", "name", "s1", value="x"),
            result("r2", "ads", "label", "s1", value="z"),
        ]
        report = analyze_violation_origins(
            results, BASE_LINEAGE, [target("ads", "label", "s1")]
        )["reports"][0]
        self.assertEqual(
            [item["rule_id"] for item in report["originEvidence"]],
            ["r2", "r1"],
        )
        self.assertEqual(
            report["originEvidence"][1]["path"],
            [
                path_node("ods", "name"),
                path_node("dwd", "label"),
                path_node("ads", "label"),
            ],
        )
        self.assertEqual(report["impactEvidence"], [])

    def test_other_samples_and_passing_results_are_ignored(self):
        results = [
            result("r1", "dwd", "label", "s1", value="y"),
            result("r2", "ods", "name", "s2", value="other-sample"),
            result("r3", "ods", "name", "s1", violated=False, value="ok"),
            result("r4", "dwd", "id", "s1", value="unrelated"),
        ]
        report = analyze_violation_origins(
            results, BASE_LINEAGE, [target("dwd", "label", "s1")]
        )["reports"][0]
        self.assertEqual(
            [item["rule_id"] for item in report["originEvidence"]], ["r1"]
        )
        self.assertEqual(report["impactEvidence"], [])

    def test_multiple_rules_on_one_field(self):
        results = [
            result("r2", "ods", "name", "s1", value="x"),
            result("r1", "ods", "name", "s1", value="x"),
            result("r3", "dwd", "label", "s1", value="y"),
        ]
        report = analyze_violation_origins(
            results, BASE_LINEAGE, [target("dwd", "label", "s1")]
        )["reports"][0]
        # Same path length and field: rule_id breaks the tie.
        self.assertEqual(
            [item["rule_id"] for item in report["originEvidence"]],
            ["r3", "r1", "r2"],
        )

    def test_self_loop_does_not_count_as_impact(self):
        loop_lineage = lineage(
            ["dwd"],
            {"dwd": ["label"]},
            [edge("dwd", "label", "dwd", "label", "downstream")],
        )
        results = [result("r1", "dwd", "label", "s1", value="bad")]
        report = analyze_violation_origins(
            results, loop_lineage, [target("dwd", "label", "s1")]
        )["reports"][0]
        self.assertEqual(len(report["originEvidence"]), 1)
        self.assertEqual(report["originEvidence"][0]["path"],
                         [path_node("dwd", "label")])
        self.assertEqual(report["impactEvidence"], [])

    def test_cycle_field_counts_as_origin_and_impact(self):
        # dwd.a -> dwd.b -> dwd.c -> dwd.a: from dwd.a the field dwd.c is
        # upstream (one edge backwards) and downstream (two edges forward).
        cycle_lineage = lineage(
            ["dwd"],
            {"dwd": ["a", "b", "c"]},
            [
                edge("dwd", "a", "dwd", "b", "downstream"),
                edge("dwd", "b", "dwd", "c", "downstream"),
                edge("dwd", "c", "dwd", "a", "downstream"),
            ],
        )
        results = [
            result("r1", "dwd", "a", "s1", value=1),
            result("r2", "dwd", "c", "s1", value=2),
        ]
        report = analyze_violation_origins(
            results, cycle_lineage, [target("dwd", "a", "s1")]
        )["reports"][0]
        self.assertEqual(
            [item["rule_id"] for item in report["originEvidence"]],
            ["r1", "r2"],
        )
        self.assertEqual(
            report["originEvidence"][1]["path"],
            [path_node("dwd", "c"), path_node("dwd", "a")],
        )
        self.assertEqual(
            [item["rule_id"] for item in report["impactEvidence"]], ["r2"]
        )
        self.assertEqual(
            report["impactEvidence"][0]["path"],
            [path_node("dwd", "a"), path_node("dwd", "b"), path_node("dwd", "c")],
        )


class OriginPathSelectionTest(unittest.TestCase):
    def test_shortest_path_wins(self):
        # ods.name reaches dwd.label directly and via ods.id; the direct
        # edge is shorter.
        graph = lineage(
            ["ods", "dwd"],
            {"ods": ["id", "name"], "dwd": ["label"]},
            [
                edge("ods", "name", "dwd", "label", "downstream"),
                edge("ods", "name", "ods", "id", "downstream"),
                edge("ods", "id", "dwd", "label", "downstream"),
            ],
        )
        results = [
            result("r1", "ods", "name", "s1", value="x"),
            result("r2", "dwd", "label", "s1", value="y"),
        ]
        report = analyze_violation_origins(
            results, graph, [target("dwd", "label", "s1")]
        )["reports"][0]
        self.assertEqual(
            report["originEvidence"][1]["path"],
            [path_node("ods", "name"), path_node("dwd", "label")],
        )

    def test_lexicographic_tie_break(self):
        # Two equal-length paths ods.name -> dwd.a -> dwd.label and
        # ods.name -> dwd.b -> dwd.label: the dwd.a sequence wins.
        graph = lineage(
            ["ods", "dwd"],
            {"ods": ["name"], "dwd": ["a", "b", "label"]},
            [
                edge("ods", "name", "dwd", "b", "downstream"),
                edge("ods", "name", "dwd", "a", "downstream"),
                edge("dwd", "a", "dwd", "label", "downstream"),
                edge("dwd", "b", "dwd", "label", "downstream"),
            ],
        )
        results = [
            result("r1", "ods", "name", "s1", value="x"),
            result("r2", "dwd", "label", "s1", value="y"),
        ]
        report = analyze_violation_origins(
            results, graph, [target("dwd", "label", "s1")]
        )["reports"][0]
        self.assertEqual(
            report["originEvidence"][1]["path"],
            [
                path_node("ods", "name"),
                path_node("dwd", "a"),
                path_node("dwd", "label"),
            ],
        )

    def test_impact_path_runs_target_to_evidence(self):
        graph = lineage(
            ["dwd", "ads", "mart"],
            {"dwd": ["label"], "ads": ["label"], "mart": ["label"]},
            [
                edge("dwd", "label", "ads", "label", "downstream"),
                edge("ads", "label", "mart", "label", "downstream"),
            ],
        )
        results = [
            result("r1", "dwd", "label", "s1", value="x"),
            result("r2", "mart", "label", "s1", value="z"),
        ]
        report = analyze_violation_origins(
            results, graph, [target("dwd", "label", "s1")]
        )["reports"][0]
        self.assertEqual(
            report["impactEvidence"][0]["path"],
            [
                path_node("dwd", "label"),
                path_node("ads", "label"),
                path_node("mart", "label"),
            ],
        )


class OriginEvidenceSortTest(unittest.TestCase):
    def test_sorted_by_path_length_then_field_then_rule(self):
        # ods.name -> dwd.label -> ads.label; dwd.id -> ads.label.
        graph = lineage(
            ["ods", "dwd", "ads"],
            {"ods": ["name"], "dwd": ["id", "label"], "ads": ["label"]},
            [
                edge("ods", "name", "dwd", "label", "downstream"),
                edge("dwd", "label", "ads", "label", "downstream"),
                edge("dwd", "id", "ads", "label", "downstream"),
            ],
        )
        results = [
            result("r4", "ods", "name", "s1", value=1),
            result("r3", "dwd", "id", "s1", value=2),
            result("r2", "dwd", "label", "s1", value=3),
            result("r1", "ads", "label", "s1", value=4),
        ]
        report = analyze_violation_origins(
            results, graph, [target("ads", "label", "s1")]
        )["reports"][0]
        # Path lengths: r1 self (1), r2/r3 one edge (2), r4 two edges (3);
        # r2 before r3 by dataset/field ("label" < "id" is false, so
        # field_id decides: dwd.id < dwd.label? dataset equal, id < label).
        self.assertEqual(
            [item["rule_id"] for item in report["originEvidence"]],
            ["r1", "r3", "r2", "r4"],
        )


class OriginTargetsOrderTest(unittest.TestCase):
