            analyze_violation_origins([], "nope", [])
        with self.assertRaises(InvalidOriginInputError):
            analyze_violation_origins(
                [],
                lineage(["dwd"], {"dwd": ["a"]}, [edge("dwd", "a", "ghost", "b")]),
                [],
            )

    def test_malformed_targets(self):
        results = [result("r1", "dwd", "label", "s1")]
        for bad_targets in (
